    def diameter(self, root: 'Node') -> int:
        self.ans = 0
        def dfs(node):
            if not node:
                return 0
            top1 = top2 = 0
            for child in node.children:
                d = dfs(child)
                if d >= top1:
                    top2 = top1
                    top1 = d
