class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        from functools import lru_cache
        n = len(s)
        def encode_len(count):
            if count == 0: return 0
            if count == 1: return 1
            if count < 10: return 2
            if count < 100: return 3
            return 4
        @lru_cache(None)
        def dp(i, k):
            if k < 0:
                return float('inf')
            if i >= n:
                return 0
            # Option 1: delete s[i]
            res = dp(i + 1, k - 1)
            # Option 2: keep s[i] and some following same chars
            count = 0
            deletes = 0
            for j in range(i, n):
                if s[j] == s[i]:
                    count += 1
                else:
                    deletes += 1
                if deletes > k:
                    break
                res = min(res, encode_len(count) + dp(j + 1, k - deletes))
            return res
        return dp(0, k)

class Solution:
    def getIndex(self, reader: 'ArrayReader') -> int:
        left, right = 0, reader.length() - 1
        while left < right:
            mid = (left + right) // 2
            length = right - left + 1
            if length % 2 == 0:
                cmp = reader.compareSub(left, mid, mid + 1, right)
            else:
                cmp = reader.compareSub(left, mid, mid, right)
