class Solution:
    def minSwaps(self, grid: List[List[int]]) -> int:
        n = len(grid)
        trailing = []
        for row in grid:
            count = 0
            for j in range(n-1, -1, -1):
                if row[j] == 0:
                    count += 1
                else:
                    break
            trailing.append(count)
        ans = 0
        for i in range(n):
            need = n - 1 - i
            j = i
            while j < n and trailing[j] < need:
                j += 1
            if j == n:
                return -1
            while j > i:
                trailing[j], trailing[j-1] = trailing[j-1], trailing[j]
                j -= 1
                ans += 1
        return ans

class Solution:
    def maxSum(self, nums1: List[int], nums2: List[int]) -> int:
        MOD = 10**9 + 7
        i, j = 0, 0
        sum1, sum2 = 0, 0
        m, n = len(nums1), len(nums2)
        while i < m and j < n:
            if nums1[i] < nums2[j]:
                sum1 += nums1[i]
                i += 1
            elif nums1[i] > nums2[j]:
                sum2 += nums2[j]
                j += 1
            else:
                sum1 = sum2 = max(sum1, sum2) + nums1[i]
                i += 1
                j += 1
        while i < m:
            sum1 += nums1[i]
            i += 1
        while j < n:
            sum2 += nums2[j]
            j += 1
        return max(sum1, sum2) % MOD

class Solution:
    def guessMajority(self, reader: 'ArrayReader') -> int:
        n = reader.length()
        base = reader.query(0, 1, 2, 3)
        same = [0]  # indices same as arr[0]
        diff = []   # indices different from arr[0]
        # Compare arr[1] with arr[0]
        q1 = reader.query(0, 2, 3, 4)
        q2 = reader.query(1, 2, 3, 4)
        if q1 == q2:
            same.append(1)
        else:
            diff.append(1)
        # Compare arr[2] with arr[0]
        q1 = reader.query(0, 1, 3, 4)
        q2 = reader.query(1, 2, 3, 4)
        if q1 == q2:
            same.append(2)
        else:
            diff.append(2)
        # Compare arr[3] with arr[0]
        q1 = reader.query(0, 1, 2, 4)
        q2 = reader.query(1, 2, 3, 4)
        if q1 == q2:
            same.append(3)
        else:
            diff.append(3)
        # For i >= 4, compare with arr[0] using query(0,1,2,i) vs base
        for i in range(4, n):
            q = reader.query(0, 1, 2, i)
            if q == base:
                same.append(i)
            else:
                diff.append(i)
        if len(same) > len(diff):
            return same[0]
        elif len(diff) > len(same):
            return diff[0]
        return -1

