class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:
        if len(s) != len(t):
            return False
        count = [0] * 26
        for a, b in zip(s, t):
            diff = (ord(b) - ord(a)) % 26
            if diff != 0:
                count[diff] += 1
        for i in range(1, 26):
            # The moves used for shift i are: i, i+26, i+52, ...
            # Need count[i] moves, last one is i + 26*(count[i]-1)
            if count[i] > 0 and i + 26 * (count[i] - 1) > k:
                return False
        return True

class Solution:
    def minInsertions(self, s: str) -> int:
        insertions = 0
        need_right = 0  # number of ')' needed
        i = 0
        while i < len(s):
            if s[i] == '(':
                need_right += 2
                if need_right % 2 == 1:
                    insertions += 1
                    need_right -= 1
            else:
                need_right -= 1
                if need_right < 0:
                    insertions += 1
                    need_right += 2
                    need_right -= 1
            i += 1
        return insertions + need_right

