    def longestAwesome(self, s: str) -> int:
        n = len(s)
        first = {0: -1}
        mask = 0
        ans = 0
        for i, ch in enumerate(s):
            mask ^= 1 << int(ch)
            if mask in first:
                ans = max(ans, i - first[mask])
            else:
