class Solution:
    def minCost(self, n: int, cuts: List[int]) -> int:
        cuts = sorted([0] + cuts + [n])
        m = len(cuts)
        dp = [[0] * m for _ in range(m)]
        for length in range(2, m):
            for i in range(m - length):
                j = i + length
                dp[i][j] = float('inf')
                for k in range(i + 1, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j] + cuts[j] - cuts[i])
        return dp[0][m-1]

class Solution:
    def mostSimilar(self, n: int, roads: List[List[int]], names: List[str], targetPath: List[str]) -> List[int]:
        from collections import defaultdict
        graph = defaultdict(list)
        for u, v in roads:
            graph[u].append(v)
            graph[v].append(u)
        m = len(targetPath)
        dp = [[float('inf')] * n for _ in range(m)]
        parent = [[-1] * n for _ in range(m)]
        for j in range(n):
            dp[0][j] = 0 if names[j] == targetPath[0] else 1
        for i in range(1, m):
            for j in range(n):
                cost = 0 if names[j] == targetPath[i] else 1
                for nei in graph[j]:
                    if dp[i-1][nei] + cost < dp[i][j]:
                        dp[i][j] = dp[i-1][nei] + cost
                        parent[i][j] = nei
        # Find best end node
        end = min(range(n), key=lambda j: dp[m-1][j])
        path = [0] * m
        path[m-1] = end
        for i in range(m-2, -1, -1):
            path[i] = parent[i+1][path[i+1]]
        return path

