class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:
        position.sort()
        def canPlace(min_dist):
            count = 1
            last = position[0]
            for i in range(1, len(position)):
                if position[i] - last >= min_dist:
                    count += 1
                    last = position[i]
            return count >= m
        left, right = 1, position[-1] - position[0]
        while left <= right:
            mid = (left + right) // 2
            if canPlace(mid):
                left = mid + 1
            else:
                right = mid - 1
        return right

class Solution:
    def minDays(self, n: int) -> int:
        from functools import lru_cache
        @lru_cache(None)
        def dp(n):
            if n <= 1:
                return n
            return 1 + min(n % 2 + dp(n // 2), n % 3 + dp(n // 3))
        return dp(n)

class Solution:
    def differByOne(self, dict: List[str]) -> bool:
        seen = set()
        for word in dict:
            for i in range(len(word)):
                pattern = word[:i] + '*' + word[i+1:]
                if pattern in seen:
                    return True
                seen.add(pattern)
